import { readBookingRequests } from './motherBookingRequests.js'
import { readRescheduleRequests, getOwnedAppointment, validLocalAppointmentTime } from './motherRescheduleRequests.js'
import { motherAppointmentDemoData } from '../pages/mother/motherAppointmentDemoData.js'
import { bookingDoctors } from '../pages/mother/bookingAvailabilityDemo.js'

// Event names and appointment payloads are an integration boundary for a future backend/email worker.
// Decision events are defined for future real server events; no decision is generated by this demo.
export const motherNotificationEvents = {
  bookingSubmitted: { tab: 'pending' }, rescheduleSubmitted: { tab: 'pending' },
  bookingApproved: { tab: 'upcoming' }, bookingRejected: { tab: 'pending' },
  rescheduleApproved: { tab: 'upcoming' }, rescheduleRejected: { tab: 'pending' },
  reminder24h: { tab: 'upcoming' }, reminder2h: { tab: 'upcoming' },
}
export const notificationStorageKey = mother => 'nomu.demo.notifications.v1:' + encodeURIComponent(mother.id)
// Frontend demo only: not secure authorization, email delivery, or multi-user synchronization.
export function readMotherNotifications(mother, storage = window.localStorage) {
  try {
    const records = JSON.parse(storage.getItem(notificationStorageKey(mother)) || '[]')
    if (!Array.isArray(records) || records.some(item => !item || item.motherId !== mother.id || typeof item.id !== 'string' || !Object.hasOwn(motherNotificationEvents, item.type) || typeof item.read !== 'boolean' || !Number.isFinite(Date.parse(item.createdAt)) || !validLocalAppointmentTime(item.dateTime) || typeof item.appointmentId !== 'string' || !mother.children.some(child => child.id === item.childId))) throw Error('notificationStorageError')
    return records
  } catch { throw Error('notificationStorageError') }
}
function write(mother, records, storage) {
  try { storage.setItem(notificationStorageKey(mother), JSON.stringify(records)) } catch { throw Error('notificationStorageError') }
  return records
}
export function syncMotherNotifications(mother, storage = window.localStorage, now = new Date(), appointments = motherAppointmentDemoData) {
  const records = readMotherNotifications(mother, storage)
  const ids = new Set(records.map(item => item.id))
  const add = (type, appointmentId, childId, doctorKey, dateTime, originalDateTime, createdAt) => {
    const id = type + ':' + appointmentId
    if (ids.has(id)) return
    records.push({ id, motherId: mother.id, type, appointmentId, childId, doctorKey, dateTime, ...(originalDateTime ? { originalDateTime } : {}), createdAt: createdAt && Number.isFinite(Date.parse(createdAt)) ? createdAt : now.toISOString(), read: false })
    ids.add(id)
  }
  for (const request of readBookingRequests(mother, storage)) {
    add('bookingSubmitted', request.id, request.childId, bookingDoctors.find(doctor => doctor.id === request.doctorId).nameKey, request.dateTime, null, request.createdAt)
  }
  for (const request of readRescheduleRequests(mother, storage)) {
    const original = getOwnedAppointment(mother, request.appointmentId)
    add('rescheduleSubmitted', request.id, original.childKey, original.doctorKey, request.dateTime, original.dateTime, request.createdAt)
  }
  for (const appointment of appointments) {
    if (appointment.motherId !== mother.id || appointment.status !== 'confirmed' || !mother.children.some(child => child.id === appointment.childKey) || !validLocalAppointmentTime(appointment.dateTime)) continue
    const remaining = new Date(appointment.dateTime).getTime() - now.getTime()
    if (remaining <= 0) continue
    // Catch up both thresholds once if the site was closed. No background delivery is claimed.
    if (remaining <= 24 * 60 * 60 * 1000) add('reminder24h', appointment.id, appointment.childKey, appointment.doctorKey, appointment.dateTime)
    if (remaining <= 2 * 60 * 60 * 1000) add('reminder2h', appointment.id, appointment.childKey, appointment.doctorKey, appointment.dateTime)
  }
  if (records.length !== ids.size) throw Error('notificationStorageError')
  if (records.length !== readMotherNotifications(mother, storage).length) write(mother, records, storage)
  return records.sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt))
}
export function markMotherNotificationsRead(mother, id, storage = window.localStorage) {
  return write(mother, readMotherNotifications(mother, storage).map(item => !id || item.id === id ? { ...item, read: true } : item), storage)
}
